<?php
namespace Tests\Unit;

use PHPUnit\Framework\TestCase;

/**
 * ══════════════════════════════════════════════════════════════════════════
 * PHASE 3 / B1 — ADMISSION ORDERING: THE DEFECT, PROVEN EXECUTABLY
 * ══════════════════════════════════════════════════════════════════════════
 *
 * B1: "When a student is admitted and an approved entitlement/concession
 * applies, the fee demand generated by that admission must be based on the
 * entitlement that was captured/approved for that admission."
 *
 * This file documents, in executing code, why that is NOT true today — and it
 * establishes the two independent reasons, because they need different fixes:
 *
 *   REASON 1 — ORDERING (B1).  save_admission() generates the demands and
 *   returns; the capture UI only mounts afterwards, in the success branch of
 *   the response handler. Nothing regenerates.
 *
 *   REASON 2 — AUTHORITY (B2). Even with perfect ordering, the generator reads
 *   `studentConcessions` through Fee_concession_reader. An entitlement lives in
 *   `studentEntitlements`. No bridge exists, so the money cannot change.
 *
 * Fixing ordering alone therefore cannot satisfy B1. That is the phase's
 * finding, and these tests are what make it undeniable rather than asserted.
 *
 * ── WHAT EXECUTES ───────────────────────────────────────────────────────────
 * The REAL Fee_generation_service (including buildAdmissionDemandSpecs via a
 * Fee_lifecycle double that supplies only the CHART), the REAL
 * Fee_concession_reader and Fee_entitlement_reader, and the REAL deduction
 * arithmetic. No fee arithmetic is re-implemented here.
 *
 * ── NO I/O ──────────────────────────────────────────────────────────────────
 * No Firestore, no network, no tenant, no admission. Nothing can be written.
 */
class Phase3B1AdmissionOrderingTest extends TestCase
{
    private const SIS_PHP  = __DIR__ . '/../../application/controllers/Sis.php';
    private const ADMIT_JS = __DIR__ . '/../../application/views/studentAdmission.php';

    public static function setUpBeforeClass(): void
    {
        if (!defined('BASEPATH')) define('BASEPATH', __DIR__);
        if (!class_exists('CI_Controller', false)) eval('class CI_Controller { public static $instance; }');
        if (!function_exists('get_instance')) eval('function &get_instance() { return \CI_Controller::$instance; }');
        foreach (['Fee_concession_reader', 'Fee_entitlement_reader', 'Fee_generation_service'] as $c) {
            if (!class_exists($c, false)) require_once __DIR__ . '/../../application/libraries/' . $c . '.php';
        }
    }

    // ── helpers ──────────────────────────────────────────────────────────

    /** Source with comments stripped, so a comment can never satisfy an assertion. */
    private function src(string $path): string
    {
        $out = '';
        foreach (token_get_all(file_get_contents($path)) as $t) {
            if (is_array($t)) {
                if (in_array($t[0], [T_COMMENT, T_DOC_COMMENT], true)) continue;
                $out .= $t[1];
            } else { $out .= $t; }
        }
        return $out;
    }

    /** The body of save_admission(), comments stripped. */
    private function saveAdmissionBody(): string
    {
        $s = $this->src(self::SIS_PHP);
        $start = strpos($s, 'public function save_admission()');
        $this->assertNotFalse($start, 'save_admission() not found.');
        $end = strpos($s, 'public function ', $start + 40);
        return substr($s, $start, ($end === false ? strlen($s) : $end) - $start);
    }

    /**
     * Price a chart through the REAL deduction algorithm using the NEW readers
     * accessors — the same three callables Fee_generation_service::_shadowCompare
     * supplies at :233-238.
     *
     * This is deliberately NOT generateDemandsForStudent(): that method hardcodes
     * the LEGACY accessors $c[type] / $c[value] at :101-102, so swapping only the
     * reader would still read the wrong fields. That is recorded as a B2
     * prerequisite by test_B2_PREREQ_generator_hardcodes_legacy_accessors().
     */
    private function netsViaEntitlements(array $rows, bool $withTransport = false): array
    {
        $built = (new B1ChartOnlyLifecycle($withTransport))->buildAdmissionDemandSpecs('STU_B1', 'Class 5th', 'Section A');
        $rdr   = new \Fee_entitlement_reader();
        $gen   = (new \ReflectionClass('Fee_generation_service'))->newInstanceWithoutConstructor();
        $m     = new \ReflectionMethod('Fee_generation_service', '_applyDeductions');
        $m->setAccessible(true);
        return $this->nets($m->invoke($gen, $built, $rows,
            fn(array $e, string $p, string $hId, string $h, string $c): bool => $rdr->appliesTo($e, $p, $hId, $h, $c),
            fn(array $e): string => $rdr->deductionType($e),
            fn(array $e): float  => $rdr->deductionValue($e)
        ));
    }

    /** A real generator wired to a chart-only Fee_lifecycle double. */
    private function generator($concessionReader): \Fee_generation_service
    {
        $g = new \Fee_generation_service();
        $g->init(new B1ChartOnlyLifecycle(), $concessionReader, null, 'SCH_B1', '2026-27');
        return $g;
    }

    private function nets(array $built): array
    {
        $m = [];
        foreach ($built['specs'] as $s) $m[$s['demandId']] = round((float) ($s['data']['netAmount'] ?? 0), 2);
        ksort($m);
        return $m;
    }

    private function entitlement(array $over = []): array
    {
        return array_merge([
            'studentId' => 'STU_B1', 'schoolId' => 'SCH_B1', 'session' => '2026-27',
            'kind' => 'concession', 'scope' => 'all', 'valueType' => 'percent', 'value' => 20,
            'effectiveFrom' => '2026-04-01', 'effectiveTo' => null, 'status' => 'active',
        ], $over);
    }

    // ══════════════════════════════════════════════════════════════════
    //  B1-01 — demands are generated BEFORE capture is possible
    // ══════════════════════════════════════════════════════════════════

    public function test_B1_01_admission_generates_demands_before_capture_is_possible(): void
    {
        $body = $this->saveAdmissionBody();

        $genPos = strpos($body, 'assignInitialFees');
        $this->assertNotFalse($genPos, 'save_admission() must still generate the initial fees.');

        // PHASE 3B / B1 — INVERTED. This previously asserted that admission did
        // NOT touch the entitlement system, which was the defect. It now asserts
        // the corrected contract: the entitlement is resolved in-request, and
        // strictly BEFORE the demands are priced.
        $resolvePos = strpos($body, '_resolve_admission_entitlement(');
        $this->assertNotFalse($resolvePos,
            'save_admission() must resolve a submitted entitlement inside the request.');
        $this->assertLessThan($genPos, $resolvePos,
            'ORDERING: the entitlement must be resolved BEFORE assignInitialFees() prices the demands.');
        $this->assertStringContainsString('Entitlement_service', $body,
            'Resolution goes through the canonical service, not a private copy.');

        // Capture is mounted only by the response handler, after HTTP 200.
        $js = file_get_contents(self::ADMIT_JS);
        $this->assertStringContainsString('ENTCAP.mount(', $js);
        // NOTE: an HTML comment earlier in the view also mentions ENTCAP.mount(),
        // so anchor on the actual call form used by the handler.
        $mountPos   = strpos($js, 'ENTCAP.mount({');
        $successPos = strpos($js, "res.status === 'success'");
        $this->assertNotFalse($successPos);
        $this->assertGreaterThan($successPos, $mountPos,
            'ENTCAP.mount() lives inside the success branch, i.e. AFTER the server already '
            . 'created the student and generated the demands.');
    }

    // ══════════════════════════════════════════════════════════════════
    //  B1-02 — an entitlement captured afterwards changes nothing
    // ══════════════════════════════════════════════════════════════════

    /**
     * THE DEFECT, numerically. A student is admitted (demands generated with no
     * concession on file), then a 20% entitlement is captured and is ACTIVE.
     * Re-running the very same production generator still bills GROSS, because
     * the authority it reads is `studentConcessions`.
     */
    public function test_B1_02_entitlement_captured_after_generation_does_not_change_the_demand(): void
    {
        // Step 1 — admission-time generation. studentConcessions is empty.
        $atAdmission = $this->nets($this->generator(new B1EmptyConcessionReader())
            ->generateDemandsForStudent('STU_B1', 'Class 5th', 'Section A'));
        $this->assertSame(['D_Tuition Fee_2026-04' => 1000.0], $atAdmission,
            'Admission bills GROSS — correct, since no concession exists yet.');

        // Step 2 — the operator captures an ACTIVE 20% entitlement.
        $ent = $this->entitlement();
        $reader = new \Fee_entitlement_reader();
        $this->assertSame('percent', $reader->deductionType($ent));
        $this->assertSame(20.0, $reader->deductionValue($ent));
        $this->assertTrue($reader->appliesTo($ent, '2026-04', 'FH_TUI', 'Tuition Fee', 'academic'),
            'The entitlement genuinely applies to this demand.');

        // Step 3 — regenerate. Same generator, same student, entitlement active.
        $afterCapture = $this->nets($this->generator(new B1EmptyConcessionReader())
            ->generateDemandsForStudent('STU_B1', 'Class 5th', 'Section A'));

        $this->assertSame($atAdmission, $afterCapture,
            'B1 DEFECT: an ACTIVE, APPLICABLE entitlement leaves the billed amount untouched. '
            . 'Ordering alone cannot fix this — the generator reads studentConcessions, and the '
            . 'entitlement is in studentEntitlements (that swap is B2).');
        $this->assertSame(1000.0, $afterCapture['D_Tuition Fee_2026-04'],
            'The student is billed the FULL 1000 despite a 20% approved concession.');
    }

    /**
     * B1-02b — the same entitlement, read through the NEW reader, WOULD have
     * changed the bill. This isolates the cause to the authority, not the data:
     * the record is correct and applicable; only the reader is wrong.
     */
    public function test_B1_02b_the_same_entitlement_would_bill_correctly_via_the_new_authority(): void
    {
        $viaEntitlement = $this->netsViaEntitlements([$this->entitlement()]);

        $this->assertSame(['D_Tuition Fee_2026-04' => 800.0], $viaEntitlement,
            'Same entitlement, same arithmetic, correct money — proving the data is fine and the '
            . 'authority is the gap. Wiring this reader in production is B2, NOT this phase.');
    }

    // ══════════════════════════════════════════════════════════════════
    //  Scenario coverage that is provable WITHOUT B2
    // ══════════════════════════════════════════════════════════════════

    /** Scenario 1 / B1-06 — no entitlement → ordinary gross billing. */
    public function test_B1_06_no_entitlement_bills_gross(): void
    {
        $this->assertSame(['D_Tuition Fee_2026-04' => 1000.0],
            $this->netsViaEntitlements([]));
    }

    /** Scenario 7 / B1-07 — a rejected entitlement never bills. */
    public function test_B1_07_rejected_entitlement_bills_gross(): void
    {
        // The reader filters status server-side; a rejected row is never a candidate.
        $rows = array_values(array_filter(
            [$this->entitlement(['status' => 'rejected'])],
            fn(array $e) => ($e['status'] ?? '') === 'active'
        ));
        $this->assertSame([], $rows, 'A rejected entitlement is not an active candidate.');
        $this->assertSame(['D_Tuition Fee_2026-04' => 1000.0],
            $this->netsViaEntitlements($rows));
    }

    /** Scenario 8 / B1-08 — an out-of-window entitlement never bills. */
    public function test_B1_08_not_yet_effective_entitlement_bills_gross(): void
    {
        $future = $this->entitlement(['effectiveFrom' => '2027-06-01']);
        $this->assertSame(['D_Tuition Fee_2026-04' => 1000.0],
            $this->netsViaEntitlements([$future]),
            'effectiveFrom is in the future — the April demand must not be discounted.');
    }

    /**
     * Scenario 2/3/4 — the approved academic value types, end to end through
     * the real generator.
     */
    public function test_B1_05_academic_entitlements_produce_the_expected_nets(): void
    {
        $cases = [
            'percent 20'  => [['valueType' => 'percent', 'value' => 20],  800.0],
            'fixed 500'   => [['valueType' => 'fixed',   'value' => 500], 500.0],
        ];
        foreach ($cases as $label => [$over, $expect]) {
            $this->assertSame(['D_Tuition Fee_2026-04' => $expect],
                $this->netsViaEntitlements([$this->entitlement($over)]),
                "Scenario '{$label}' must bill {$expect}.");
        }

        // Scenario 4 — full academic exemption drops the demand entirely.
        $this->assertSame([],
            $this->netsViaEntitlements([$this->entitlement(['valueType' => 'fullExempt', 'value' => 0])]));
    }

    /**
     * Scenario 6 / B1-09 — the APPROVED F2 rule, restated at the admission
     * level: an academic concession must not discount transport.
     */
    public function test_B1_09_academic_concession_never_discounts_transport(): void
    {
        $nets = $this->netsViaEntitlements([$this->entitlement()], /* withTransport */ true);

        $this->assertSame(800.0, $nets['D_Tuition Fee_2026-04'], 'Academic head: 20% applies.');
        $this->assertSame(800.0, $nets['D_Bus Fee_2026-04'],
            'Transport head: the blanket academic concession must NOT apply (F2, operator-approved).');
    }

    // ══════════════════════════════════════════════════════════════════
    //  Identity / idempotency guarantees that already hold
    // ══════════════════════════════════════════════════════════════════

    /** B1-13 — admission mints the Student ID exactly once, before any write. */
    public function test_B1_13_student_id_minted_exactly_once(): void
    {
        $body = $this->saveAdmissionBody();
        $this->assertSame(1, substr_count($body, '_nextStudentId('),
            'Exactly one Student ID mint per admission request.');
        $this->assertLessThan(strpos($body, '_placeStudentGuarded('), strpos($body, '_nextStudentId('),
            'The id is minted before the student write, as the guarded-placement contract requires.');
        $this->assertStringContainsString('already exists', $body,
            'A duplicate id is refused rather than overwriting an existing student.');
    }

    /** B1-10/B1-12 — demand ids are deterministic, so a retry overwrites rather than duplicates. */
    public function test_B1_10_12_regeneration_is_idempotent_not_additive(): void
    {
        $a = $this->netsViaEntitlements([$this->entitlement()]);
        $b = $this->netsViaEntitlements([$this->entitlement()]);

        $this->assertSame($a, $b, 'Two generations produce the same demand ids and the same money.');
        $this->assertCount(1, $a, 'One head, one period, one demand — never two.');
    }

    /** B1-11 — the failure path that currently reports success is pinned as a KNOWN gap (B6). */
    public function test_B1_11_fee_generation_failure_is_reported_not_swallowed(): void
    {
        $body = $this->saveAdmissionBody();
        $pos  = strpos($body, 'assignInitialFees');
        // Widened: the billing-state assignment sits a few statements after the
        // call, and the point is that the FAILURE PATH is honest, not that the
        // words are adjacent.
        $window = substr($body, max(0, $pos - 400), 1600);

        $this->assertStringContainsString('catch', $window,
            'assignInitialFees() is still wrapped — the student exists by now, so aborting the '
            . 'request would leave a half-made admission, which is worse.');

        // PHASE 3B / B6 — INVERTED. This previously asserted the failure was
        // SWALLOWED. It now asserts the honest contract: a failure downgrades
        // the billing state and the response carries it.
        $this->assertStringContainsString('billing_failed', $window,
            'A fee-generation failure must set an explicit billing state, not be swallowed.');
        $this->assertStringContainsString('ACC_ADMISSION_BILLING_FAILED', $body,
            'and must leave a greppable log line.');
        $this->assertStringContainsString('ACC_ADMISSION_BILLING_EMPTY', $body,
            'Zero demands WITHOUT an exception is equally a billing failure and is caught too.');
        $this->assertStringContainsString("'billing_state'", $body,
            'The response must carry the billing state so the UI cannot infer success.');
    }

    /**
     * B2 PREREQUISITE, discovered while building this file — recorded, NOT fixed.
     *
     * `generateDemandsForStudent()` does not ask the reader for the deduction
     * type and value. It hardcodes the LEGACY field names inline:
     *
     *     fn(array $c): string => (string) ($c['type']  ?? '')      // :101
     *     fn(array $c): float  => (float)  ($c['value'] ?? 0)       // :102
     *
     * An entitlement stores those as `valueType` / `value`. So swapping
     * Fee_concession_reader for Fee_entitlement_reader would read the right
     * ROWS through the wrong FIELDS: `type` would resolve to '', no branch would
     * match, and every entitlement would silently deduct ZERO — the exact
     * "approved concession, gross bill" failure this programme exists to close.
     *
     * The shadow path already does it correctly (`:233-238` asks the reader via
     * deductionType()/deductionValue()), so the fix is to use those accessors on
     * the authoritative path too. That is B2 work and is deliberately NOT done
     * here; this test exists so B2 cannot be attempted without knowing about it.
     */
    public function test_B2_PREREQ_generator_uses_the_reader_accessor_boundary(): void
    {
        $src = preg_replace('/\s+/', '', $this->src(__DIR__ . '/../../application/libraries/Fee_generation_service.php'));

        // PHASE 3B / PART 1 — INVERTED. This previously asserted the generator
        // HARDCODED the legacy accessors, which is exactly what would have made
        // the reader swap deduct zero. It now asserts the boundary exists.
        $this->assertStringNotContainsString("\$c['type']", $src,
            'The generator must no longer name the LEGACY field.');
        $this->assertStringNotContainsString("\$c['valueType']", $src,
            'nor the ENTITLEMENT field — it must ask the reader for both.');
        $this->assertStringContainsString('deductionType(', $src);
        $this->assertStringContainsString('deductionValue(', $src);

        // And the entitlement reader exposes the accessors that must replace them.
        $rdr = new \Fee_entitlement_reader();
        $ent = $this->entitlement(['valueType' => 'percent', 'value' => 20]);
        $this->assertSame('percent', $rdr->deductionType($ent));
        $this->assertSame(20.0, $rdr->deductionValue($ent));
        $this->assertSame('', (string) ($ent['type'] ?? ''),
            'An entitlement has no `type` field at all — which is why the inline accessor '
            . 'would silently yield a zero deduction. B2 must swap the accessors, not just the reader.');
    }

    /** B1-14/B1-15 — history/audit and parent sync remain in the admission path. */
    public function test_B1_14_15_history_audit_and_parent_sync_present(): void
    {
        $body = $this->saveAdmissionBody();
        foreach (['_log_history', 'log_audit', 'syncParent'] as $needle) {
            $this->assertStringContainsString($needle, $body,
                "{$needle} must remain part of admission — B1 must not disturb it.");
        }
    }
}

// ══════════════════════════════════════════════════════════════════════════
//  Doubles — they supply DATA only. All pricing is production code.
// ══════════════════════════════════════════════════════════════════════════

/** Supplies the chart-derived base specs; performs no pricing of its own. */
class B1ChartOnlyLifecycle
{
    public function __construct(private bool $withTransport = false) {}

    public function buildAdmissionDemandSpecs($studentId, $class, $section, $forPreview = false): array
    {
        $heads = [['FH_TUI', 'Tuition Fee', 'academic', 1000.0]];
        if ($this->withTransport) $heads[] = ['FH_BUS', 'Bus Fee', 'transport', 800.0];

        $specs = [];
        foreach ($heads as [$id, $name, $cat, $amt]) {
            $specs[] = ['demandId' => "D_{$name}_2026-04", 'data' => [
                'studentId' => $studentId, 'periodKey' => '2026-04',
                'feeHeadId' => $id, 'feeHead' => $name, 'category' => $cat,
                'grossAmount' => $amt, 'netAmount' => $amt, 'balance' => $amt, 'status' => 'unpaid',
            ]];
        }
        return ['specs' => $specs, 'assigned' => array_column($heads, 1), 'chartFound' => true];
    }
}

/** The production reality today: studentConcessions is empty. */
class B1EmptyConcessionReader
{
    public function init($firebase): void {}
    public function activeConcessionsForStudent(string $s, string $st, string $sess): array { return []; }
    public function appliesTo(array $c, string $p, string $hId, string $h, string $cat = ''): bool { return false; }
}

/**
 * Feeds entitlement rows through the REAL Fee_entitlement_reader matcher, so
 * this double decides nothing about applicability or value — it only supplies
 * the candidate set the production reader would have fetched.
 */
class B1EntitlementBackedReader
{
    private \Fee_entitlement_reader $real;

    public function __construct(private array $rows)
    {
        $this->real = new \Fee_entitlement_reader();
    }

    public function init($firebase): void {}
    public function activeConcessionsForStudent(string $s, string $st, string $sess): array { return $this->rows; }
    public function appliesTo(array $e, string $p, string $hId, string $h, string $cat = ''): bool
    {
        return $this->real->appliesTo($e, $p, $hId, $h, $cat);
    }
}
